// Writes product/sdk/tools.gen.ts from product/shared/tool-catalog.json: one input type per tool (from the validators'
// JSON Schemas), the tool names, and each tool's risk class. Run after tool-catalog.ts:
//   node --import tsx product/scripts/tool-catalog.ts && node --import tsx product/scripts/sdk-gen.ts
// tests/sdk.test.ts fails when the generated file is out of date with the catalog.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

type Schema = Record<string, any>;
const IDENT = /^[A-Za-z_$][\w$]*$/;
const key = (k: string) => (IDENT.test(k) ? k : JSON.stringify(k));

/** A JSON Schema as a TypeScript type (the subset the validators emit). */
export function tsType(s: Schema | undefined, pad = ''): string {
  if (!s || typeof s !== 'object') return 'unknown';
  if (Array.isArray(s.enum)) return s.enum.map(v => JSON.stringify(v)).join(' | ');
  if (s.type === 'string') return 'string';
  if (s.type === 'integer' || s.type === 'number') return 'number';
  if (s.type === 'boolean') return 'boolean';
  if (s.type === 'array') { const t = tsType(s.items, pad); return /[|&{]/.test(t) ? `(${t})[]` : `${t}[]`; }
  if (s.type === 'object' && s.properties) {
    const req = new Set<string>(s.required ?? []);
    const inner = pad + '  ';
    const lines = Object.entries(s.properties as Record<string, Schema>).map(([k, v]) =>
      `${v.description ? `${inner}/** ${String(v.description).replace(/\*\//g, '*\\/')} */\n` : ''}${inner}${key(k)}${req.has(k) ? '' : '?'}: ${tsType(v, inner)};`);
    return lines.length ? `{\n${lines.join('\n')}\n${pad}}` : 'Record<string, never>';
  }
  if (s.type === 'object' && s.additionalProperties && typeof s.additionalProperties === 'object') return `Record<string, ${tsType(s.additionalProperties, pad)}>`;
  if (s.type === 'object') return 'Record<string, unknown>';
  return 'unknown';
}

export function generate(catalog: { tools: { name: string; risk: string; summary: string; needsApproval: boolean; input: Schema }[] }): string {
  const tools = [...catalog.tools].sort((a, b) => a.name.localeCompare(b.name));
  return [
    '// GENERATED by product/scripts/sdk-gen.ts from product/shared/tool-catalog.json. Do not edit by hand.',
    '',
    `export type ToolName =\n${tools.map(t => `  | ${JSON.stringify(t.name)}`).join('\n')};`,
    '',
    '/** The input of each tool, from its validator\'s JSON Schema. Unknown fields are refused by the server. */',
    'export interface ToolInput {',
    ...tools.map(t => `  /** ${t.summary.replace(/\*\//g, '*\\/')} (${t.risk}${t.needsApproval ? ', waits for approval' : ''}) */\n  ${JSON.stringify(t.name)}: ${tsType(t.input, '  ')};`),
    '}',
    '',
    '/** Risk class per tool; needsApproval tools return an approval card instead of running. */',
    `export const TOOLS: Record<ToolName, { risk: string; needsApproval: boolean }> = {\n${tools.map(t => `  ${JSON.stringify(t.name)}: { risk: ${JSON.stringify(t.risk)}, needsApproval: ${t.needsApproval} },`).join('\n')}\n};`,
    '',
  ].join('\n');
}

const catalogPath = fileURLToPath(new URL('../shared/tool-catalog.json', import.meta.url));
export const outPath = fileURLToPath(new URL('../sdk/tools.gen.ts', import.meta.url));
export const generateFromCatalog = () => generate(JSON.parse(readFileSync(catalogPath, 'utf8')));

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(outPath, generateFromCatalog());
  console.log(`wrote ${outPath}`);
}
